actionConfiguration.body:
with deleted as (
	select *
	from public.set_venue_deleted(
		{{ appsmith.user.email }}::text,
		{{
		Number(
			appsmith.store.current_venue_id ||
			tblVenues.selectedRow?.id ||
			0
		)
		}}::bigint,
		{{ appsmith.store.current_client_id }}::uuid,
		true
	)
)
select
    {{
Number(
	appsmith.store.current_venue_id ||
	tblVenues.selectedRow?.id ||
	0
)
}}::bigint as id
from deleted;
